const fs = require("node:fs");
const vm = require("node:vm");
const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/app.js", "utf8");

for (const language of ["en", "zh"]) {
  const elements = new Map();
  const calls = { arcs: [], labels: [] };
  const getElementById = (id) => {
    if (!elements.has(id)) {
      elements.set(id, {
        value: "", textContent: "", innerHTML: "", width: 800, height: 500,
        listeners: {}, addEventListener(type, fn) { this.listeners[type] = fn; },
        setAttribute() {},
      });
    }
    return elements.get(id);
  };
  const ctx = new Proxy({
    measureText(text) { return { width: [...String(text)].length * 9 }; },
    fillText(text, x, y) { calls.labels.push({ text: String(text), x, y }); },
    arc(x, y, radius) { calls.arcs.push({ x, y, radius }); },
  }, { get(target, key) { return key in target ? target[key] : () => {}; } });
  getElementById("light-curve").getContext = () => ctx;
  getElementById("star-radius").value = "695700";
  getElementById("planet-radius").value = "6371";
  getElementById("noise-number").value = "500";
  getElementById("noise-level").value = "500";
  getElementById("observation-count").value = "101";
  const document = {
    documentElement: { lang: "" }, title: "", getElementById,
    querySelectorAll: () => [],
  };
  vm.runInNewContext(source, {
    document, localStorage: { getItem: () => language, setItem() {} },
    Math: Object.create(Math), Number,
  });
  getElementById("simulate-button").listeners.click();
  const dataPoints = calls.arcs.filter(({ radius }) => radius === 3);
  if (dataPoints.length !== 101) throw new Error(`${language}: expected 101 observation points`);
  if (dataPoints.some(({ y }) => y < 38 || y > 397)) {
    throw new Error(`${language}: noisy points escape the plot bounds`);
  }
  const minusFive = calls.labels.find(({ text }) => text === "−5");
  const zero = calls.labels.find(({ text }) => text === "0");
  const plusFive = calls.labels.find(({ text }) => text === "+5");
  const axisTitle = calls.labels.find(({ text }) => text.includes("position") || text.includes("相对位置"));
  const legend = calls.labels.find(({ text }) => text === (language === "en" ? "Ideal curve" : "理论曲线"));
  if (!(minusFive.y > 400 && zero.y === minusFive.y && plusFive.y === minusFive.y)) throw new Error(`${language}: x ticks not lowered below axis`);
  if (!(axisTitle.y < legend.y)) throw new Error(`${language}: x-axis title overlaps legend`);
  console.log(`${language}: chart points contained; x-axis ticks and title separated from legend`);
}

const fs = require("node:fs");
const vm = require("node:vm");
const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/app.js", "utf8") +
  "\nglobalThis.checks = { getDetectionLevel, getDetectionConclusion, translations };";

function makeContext(language) {
  const elements = new Map();
  const getElementById = (id) => {
    if (!elements.has(id)) {
      const element = {
        value: id === "star-radius" ? "695700" :
          id === "planet-radius" ? "6371" :
          ["noise-level", "noise-number"].includes(id) ? "50" :
          id === "observation-count" ? "101" : "",
        textContent: "",
        innerHTML: "",
        width: 800,
        height: 500,
        addEventListener() {},
        setAttribute() {},
        getContext() {
          return new Proxy({ measureText: (text) => ({ width: String(text).length * 8 }) }, {
            get: (target, key) => target[key] || (() => {}),
          });
        },
      };
      elements.set(id, element);
    }
    return elements.get(id);
  };
  const document = {
    documentElement: { lang: language },
    title: "",
    getElementById,
    querySelectorAll: () => [],
  };
  const sandbox = {
    document,
    localStorage: { getItem: () => language, setItem() {} },
    Math,
    Number,
  };
  vm.runInNewContext(source, sandbox);
  return sandbox.checks;
}

const bands = [
  [2, "noDetection"],
  [4, "weakCandidate"],
  [6, "tentative"],
  [8, "clear"],
  [15, "strong"],
  [25, "veryStrong"],
];
for (const language of ["en", "zh"]) {
  const { getDetectionLevel, getDetectionConclusion, translations } = makeContext(language);
  for (const [snr, expectedKey] of bands) {
    if (getDetectionLevel(snr) !== translations[language][expectedKey]) {
      throw new Error(`${language}: unexpected detection label for SNR ${snr}`);
    }
    if (!getDetectionConclusion(snr)) {
      throw new Error(`${language}: missing interpretation for SNR ${snr}`);
    }
  }
  console.log(`${language}: all six SNR interpretation bands passed`);
}

const fs = require("node:fs");
const vm = require("node:vm");
const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/home.js", "utf8");
const translations = new Map();
const languageButton = { textContent: "", listeners: {}, addEventListener(type, fn) { this.listeners[type] = fn; }, setAttribute(name, value) { this[name] = value; } };
const brand = { setAttribute(name, value) { this[name] = value; } };
const document = {
  documentElement: { lang: "" },
  title: "",
  getElementById(id) { return id === "language-button" ? languageButton : brand; },
  querySelectorAll() { return [...translations.values()]; },
};
for (const key of ["brand", "homeLabel", "eyebrow", "title", "subtitle", "collection", "modulesTitle", "moduleCount", "available", "moduleOne", "transitTitle", "transitDescription", "openModule", "inProgress", "moduleTwo", "solarTitle", "solarDescription", "comingSoon", "footer"]) {
  translations.set(key, { dataset: { i18n: key }, textContent: "" });
}
const storage = { value: "invalid-language", getItem() { return this.value; }, setItem(_, value) { this.value = value; } };
vm.runInNewContext(source, { document, localStorage: storage });
if (document.documentElement.lang !== "en" || !brand["aria-label"].includes("home")) throw new Error("invalid language did not safely fall back to English");
languageButton.listeners.click();
if (document.documentElement.lang !== "zh" || brand["aria-label"] !== "宇宙探索主页") throw new Error("Chinese translation or accessible label failed");
if (storage.value !== "zh") throw new Error("language preference not persisted");
console.log("homepage language fallback, toggle, persistence, and accessible label: passed");

const fs = require("node:fs");
const vm = require("node:vm");
const root = "/Users/zzhao08/localRepo/universe/web";
const html = fs.readFileSync(`${root}/solar.html`, "utf8");
const source = fs.readFileSync(`${root}/solar.js`, "utf8");
const ids = ["sun", "mercury", "venus", "earth", "mars", "jupiter", "saturn", "uranus", "neptune"];
const textNodes = [...html.matchAll(/data-i18n="([^"]+)"/g)].map((m) => ({ dataset: { i18n: m[1] }, textContent: "" }));
const ariaNodes = [...html.matchAll(/data-i18n-aria-label="([^"]+)"/g)].map((m) => ({ dataset: { i18nAriaLabel: m[1] }, setAttribute(k, v) { this[k] = v; } }));
function button(id) { return { dataset: { planet: id }, attributes: {}, classList: { toggle() {} }, setAttribute(k, v) { this.attributes[k] = v; }, addEventListener(type, fn) { this[`on${type}`] = fn; } }; }
const choiceButtons = ids.map(button);
const sizeButtons = [];
const elements = new Map();
function element(id) { if (!elements.has(id)) elements.set(id, { id, textContent: "", dataset: {}, attributes: {}, listeners: {}, classList: { toggle() {}, add() {}, remove() {} }, setAttribute(k,v) { this.attributes[k] = v; }, addEventListener(type,fn) { this.listeners[type] = fn; }, querySelectorAll(selector) { return selector === ".size-planet" ? sizeButtons : []; } }); return elements.get(id); }
Object.defineProperty(element("size-comparison"), "innerHTML", { set(value) { this._html = value; sizeButtons.length = 0; for (const m of value.matchAll(/data-planet="([^"]+)"/g)) sizeButtons.push({ dataset: { planet: m[1] }, addEventListener(type,fn) { this[`on${type}`]=fn; } }); }, get() { return this._html || ""; } });
const document = { documentElement: { lang: "" }, title: "", getElementById: element, querySelectorAll(selector) { if(selector === "[data-i18n]") return textNodes; if(selector === "[data-i18n-aria-label]") return ariaNodes; if(selector === ".planet-choice") return choiceButtons; return []; } };
const localStorage = { language: "en", getItem() { return this.language; }, setItem(_,value) { this.language=value; } };
const sandbox = { document, localStorage, window: { matchMedia: () => ({ matches: false }) }, Number, Math, Intl };
vm.runInNewContext(source, sandbox);
choiceButtons.find((b) => b.dataset.planet === "sun").onclick();
if (element("planet-detail-title").textContent !== "Sun") throw Error("Sun detail did not open");
if (!element("planet-diameter").textContent.includes("1,392,700")) throw Error("Sun diameter missing");
if (element("planet-distance-label").textContent !== "Stellar classification" || element("planet-distance").textContent !== "G2V (yellow dwarf)") throw Error("Sun classification missing");
if (!element("planet-period").textContent.includes("5,500") || !element("planet-moons").textContent.includes("4.6 billion")) throw Error("Sun temperature or age missing");
if (element("kepler-ratio").textContent !== "" || !element("kepler-check").textContent.includes("does not orbit itself")) throw Error("Sun Kepler exception incorrect");
if (choiceButtons.find((b) => b.dataset.planet === "sun").attributes["aria-pressed"] !== "true") throw Error("Sun selector state missing");
if (sizeButtons.some((b) => b.dataset.planet === "sun")) throw Error("Sun incorrectly included in planet-only size comparison");
localStorage.language = "en";
choiceButtons.find((b) => b.dataset.planet === "earth").onclick();
element("language-button").listeners.click();
if (element("planet-detail-title").textContent !== "地球") throw Error("Planet selection lost on language change");
choiceButtons.find((b) => b.dataset.planet === "sun").onclick();
if (element("planet-detail-title").textContent !== "太阳" || element("planet-distance-label").textContent !== "恒星分类") throw Error("Sun profile did not translate");
console.log("Sun facts, star-specific labels, Kepler note, selector state, planet-only comparison, and bilingual selection: passed");

const fs = require("node:fs");
const vm = require("node:vm");
const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/app.js", "utf8");

function createPage({ noise = "0", star = "695700", planet = "6371", count = "101" } = {}) {
  const elements = new Map();
  let clears = 0;
  let draws = 0;
  const ctx = new Proxy({
    measureText: (text) => ({ width: String(text).length * 8 }),
    clearRect() { clears++; },
    fillText() {},
  }, { get(target, key) { return key in target ? target[key] : () => { draws++; }; } });
  const getElementById = (id) => {
    if (!elements.has(id)) {
      elements.set(id, {
        id,
        value: id === "star-radius" ? star :
          id === "planet-radius" ? planet :
          id === "noise-level" || id === "noise-number" ? noise :
          id === "observation-count" ? count : "",
        textContent: "",
        innerHTML: "",
        width: 800,
        height: 500,
        listeners: {},
        attributes: {},
        addEventListener(type, fn) { this.listeners[type] = fn; },
        setAttribute(name, value) { this.attributes[name] = value; },
        getContext() { return ctx; },
      });
    }
    return elements.get(id);
  };
  const document = {
    documentElement: { lang: "" },
    title: "",
    getElementById,
    querySelectorAll: () => [],
  };
  const storage = { value: "en", getItem() { return this.value; }, setItem(_, value) { this.value = value; } };
  const math = Object.create(Math);
  math.random = () => 0.5;
  vm.runInNewContext(source, { document, localStorage: storage, Math: math, Number });
  return { elements, storage, get: getElementById, get clears() { return clears; }, get draws() { return draws; } };
}

const exact = createPage({ noise: "0" });
exact.get("simulate-button").listeners.click();
const exactRadius = Number(exact.get("results").innerHTML.match(/Planet radius estimated from noisy observations \(km\): ([0-9.]+)/)?.[1]);
if (!Number.isFinite(exactRadius) || Math.abs(exactRadius - 6371) > 0.01) {
  throw new Error(`Zero-noise fit should recover input radius, got ${exactRadius}`);
}
console.log("zero-noise fit recovers input radius: passed");

const noisy = createPage({ noise: "50", star: "695700", planet: "6371", count: "87" });
noisy.get("simulate-button").listeners.click();
const originalResults = noisy.get("results").innerHTML;
const estimatedRadius = Number(originalResults.match(/Planet radius estimated from noisy observations \(km\): ([0-9.]+)/)?.[1]);
if (!Number.isFinite(estimatedRadius) || estimatedRadius === 6371) {
  throw new Error(`Noisy-data estimate did not respond to sampled noise: ${estimatedRadius}`);
}
if (!originalResults.includes("Transit depth fitted to noisy observations")) throw new Error("Fitted depth is not separately reported");
const originalDraws = noisy.draws;
noisy.get("language-button").listeners.click();
if (Number(noisy.get("star-radius").value) !== 695700 || Number(noisy.get("planet-radius").value) !== 6371 || Number(noisy.get("noise-number").value) !== 50 || Number(noisy.get("observation-count").value) !== 87) {
  throw new Error("Language change reset current inputs");
}
if (!noisy.get("results").innerHTML.includes("根据带噪声观测估算的行星半径")) {
  throw new Error("Results were not translated after language change");
}
const localizedRadius = Number(noisy.get("results").innerHTML.match(/根据带噪声观测估算的行星半径（公里）: ([0-9.]+)/)?.[1]);
if (localizedRadius !== estimatedRadius) throw new Error("Language change changed the estimated radius");
if (!noisy.get("chart-summary").textContent.includes("观测点数: 87") || noisy.draws <= originalDraws) {
  throw new Error("Chart was not preserved/redrawn with localized accessible summary");
}
console.log("noise-based fit and input/result/chart retention on language toggle: passed");

const fs = require("node:fs");
const vm = require("node:vm");

const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/app.js", "utf8");

function simulate(values = {}) {
  const elements = new Map();
  const getElementById = (id) => {
    if (!elements.has(id)) {
      const element = {
        id,
        value: "",
        textContent: "",
        innerHTML: "",
        listeners: {},
        addEventListener(type, callback) { this.listeners[type] = callback; },
        setAttribute() {},
      };
      elements.set(id, element);
    }
    return elements.get(id);
  };
  const context2d = new Proxy({ measureText: (text) => ({ width: String(text).length * 7 }) }, {
    get(target, key) {
      if (key in target) return target[key];
      return () => {};
    },
  });
  const canvas = getElementById("light-curve");
  canvas.width = 800;
  canvas.height = 460;
  canvas.getContext = () => context2d;
  Object.assign(getElementById("star-radius"), { value: "695700" }, values.starRadius && { value: values.starRadius });
  Object.assign(getElementById("planet-radius"), { value: "6371" }, values.planetRadius && { value: values.planetRadius });
  Object.assign(getElementById("noise-number"), { value: Object.hasOwn(values, "noise") ? values.noise : "50" });
  Object.assign(getElementById("noise-level"), { value: "50" });
  Object.assign(getElementById("observation-count"), { value: "101" }, values.observationCount && { value: values.observationCount });
  const document = {
    documentElement: { lang: "en" },
    title: "",
    getElementById,
    querySelectorAll: () => [],
  };
  const sandbox = {
    document,
    localStorage: { getItem: () => "en", setItem() {} },
    Math,
    Number,
    console,
  };
  vm.runInNewContext(source, sandbox);
  if (Object.hasOwn(values, "noise")) {
    getElementById("noise-number").value = values.noise;
  }
  getElementById("simulate-button").listeners.click();
  return { elements, context2d };
}

function expectError(label, values, expected) {
  const { elements } = simulate(values);
  const message = elements.get("results").textContent;
  if (!message.includes(expected)) throw new Error(`${label}: expected ${expected}, got ${message}`);
  console.log(`${label}: passed`);
}

const normal = simulate();
if (!normal.elements.get("simulation-status").textContent.includes("complete")) throw new Error("normal simulation did not complete");
if (!normal.elements.get("chart-summary").textContent.includes("101")) throw new Error("chart summary missing observation count");
console.log("normal simulation and accessible summary: passed");
expectError("non-finite star radius", { starRadius: "Infinity" }, "greater than zero");
expectError("planet larger than star", { starRadius: "10", planetRadius: "11" }, "cannot be larger");
expectError("empty noise", { noise: "" }, "valid noise value");
expectError("too few observations", { observationCount: "1" }, "between 2 and 1000");
const noiseless = simulate({ noise: "0" });
if (!noiseless.elements.get("results").innerHTML.includes("∞")) throw new Error("zero-noise SNR boundary failed");
console.log("zero-noise boundary: passed");
